package com.inovagab.inovagab.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.*;
@Document(collection="projetos") public class Projeto { @Id private String id; private String nome,descricao,estrategiaId,status,resultados; private double investimento,retornoFinanceiro; private int progresso; private LocalDate prazo; private Instant dataAtualizacao=Instant.now(); public Projeto(){} public Projeto(String nome,String descricao,String estrategiaId,double investimento,LocalDate prazo){this.nome=nome;this.descricao=descricao;this.estrategiaId=estrategiaId;this.investimento=investimento;this.prazo=prazo;this.status="PLANEJADO";} public String getId(){return id;} public String getNome(){return nome;} public String getDescricao(){return descricao;} public String getEstrategiaId(){return estrategiaId;} public String getStatus(){return status;} public String getResultados(){return resultados;} public double getInvestimento(){return investimento;} public double getRetornoFinanceiro(){return retornoFinanceiro;} public int getProgresso(){return progresso;} public LocalDate getPrazo(){return prazo;} public Instant getDataAtualizacao(){return dataAtualizacao;} public void atualizar(String nome,String descricao,double investimento,LocalDate prazo,String status){this.nome=nome;this.descricao=descricao;this.investimento=investimento;this.prazo=prazo;this.status=status;dataAtualizacao=Instant.now();} public void progresso(int p){progresso=p;status=p==100?"CONCLUIDO":"EM_ANDAMENTO";dataAtualizacao=Instant.now();} public void resultados(String r,double retorno){resultados=r;retornoFinanceiro=retorno;dataAtualizacao=Instant.now();} }
